import{_ as t,a as n}from"./chunks/handle-2.BHurypIe.js";import{_ as i}from"./chunks/packing-8.BybpqEe_.js";import{_ as r,o,c as s,a5 as e}from"./chunks/framework.DGp912Ge.js";const _=JSON.parse('{"title":"취급 및 운송","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/safety/handling-and-transportation.md","filePath":"ko/manual/safety/handling-and-transportation.md","lastUpdated":1785806767000}'),l={name:"ko/manual/safety/handling-and-transportation.md"};function d(g,a,c,h,u,p){return o(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="취급-및-운송" tabindex="-1">취급 및 운송 <a class="header-anchor" href="#취급-및-운송" aria-label="Permalink to &quot;취급 및 운송&quot;">​</a></h1><p>RBQ를 이동·포장·운송할 때의 안전한 취급 방법입니다. 포장·개봉 절차는 <a href="/RBQ/ko/manual/operation/packing.html">포장</a>에서도 확인할 수 있습니다.</p><h2 id="이동-시-일반-주의" tabindex="-1">이동 시 일반 주의 <a class="header-anchor" href="#이동-시-일반-주의" aria-label="Permalink to &quot;이동 시 일반 주의&quot;">​</a></h2><ul><li><strong>전원 끄기</strong>: 이동·들기 전에 <strong>반드시 전원을 끄세요.</strong> 전원이 켜진 상태에서 들거나 끌어당기면 다리가 움직여 위험합니다.</li><li>로봇은 무겁고 관절이 움직일 수 있으므로, 넘어지지 않도록 받쳐서 옮기거나 지정된 캐리·이동 방법을 사용하세요.</li></ul><h3 id="끼임-주의·핸들-사용" tabindex="-1">끼임 주의·핸들 사용 <a class="header-anchor" href="#끼임-주의·핸들-사용" aria-label="Permalink to &quot;끼임 주의·핸들 사용&quot;">​</a></h3><ul><li><strong>손가락·옷·긴 머리·장신구</strong>가 핸들·관절 부근에 끼지 않도록 주의하세요. 손은 <strong>주먹을 쥔 형태</strong>로 핸들을 잡고, 끼일 여지가 있는 부분에 손가락을 넣지 마세요.</li></ul><figure><img src="'+t+'" alt="핸들을 주먹으로 잡는 올바른 자세" style="max-width:100%;width:min(420px, 100%);display:block;margin:0 auto;"><figcaption style="text-align:center;">[ 핸들은 주먹을 쥔 형태로 잡고, 손가락이 끼이지 않도록 하세요. ]</figcaption></figure><h3 id="들어-올리기" tabindex="-1">들어 올리기 <a class="header-anchor" href="#들어-올리기" aria-label="Permalink to &quot;들어 올리기&quot;">​</a></h3><ul><li>RBQ를 들어 올릴 때는 <strong>반드시 2명</strong>이 앞뒤에서 같이 듭니다. <strong>한 손으로는 좌·우 다리(또는 몸체 측면)를 받쳐 잡고</strong>, <strong>다른 한 손으로는 핸들을 주먹 쥔 형태로 잡은 뒤</strong>, <strong>핸들을 기준으로 들어 올려</strong> 로봇 전체가 수평·안정을 유지하도록 하세요. 한쪽만 들거나 비틀리면 다리가 빠지거나 무게 중심이 틀어질 수 있습니다.</li><li>RBQ는 <strong>모듈형 구성</strong>입니다. 일체형 본체와 달리 <strong>조립·분리되는 부품이 바닥에 떨어질 가능성이 있습니다.</strong> 들 때·옮길 때 충격·비틀림을 주지 말고, 바닥에 떨어뜨리지 않도록 두 사람이 호흡을 맞춰 천천히 이동하세요.</li></ul><figure><img src="'+n+'" alt="2명이 앞뒤에서 들어 올리는 모습" style="max-width:100%;width:min(420px, 100%);display:block;margin:0 auto;"><figcaption style="text-align:center;">[ 한 손은 좌·우 다리를 잡고, 다른 손은 핸들을 잡아 핸들을 들어 올려 전체를 안정적으로 옮기세요. ]</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>전원이 켜진 상태에서 무리하게 들어 올리거나 끌어당기지 마세요. 먼저 전원을 끄고 안정된 자세로 고정한 뒤 이동하세요. 모듈형이라 일체형보다 분리·낙하에 취약할 수 있으니, 충격·낙하에 특히 유의하세요.</p></div></div><h2 id="포장·운송" tabindex="-1">포장·운송 <a class="header-anchor" href="#포장·운송" aria-label="Permalink to &quot;포장·운송&quot;">​</a></h2><figure><img src="'+i+'" alt="로봇 포장·박스 고정 예시"><figcaption style="text-align:center;">[ 원래 포장재로 운송하고 박스 안에서 움직이지 않게 고정하세요 ]</figcaption></figure><ul><li><strong>원래 포장</strong>: 가능한 경우 제품 동봉 포장재를 사용해 운송하세요. 충격·흔들림으로 내부 부품이 손상될 수 있습니다.</li><li><strong>고정</strong>: 박스 안에서 로봇이 움직이지 않도록 완충재로 고정하세요.</li><li><strong>표시</strong>: 취급 주의(상하 구분, 깨짐 주의 등) 표시를 하고, 과도한 적재·던지기를 피하세요.</li></ul><h2 id="배터리" tabindex="-1">배터리 <a class="header-anchor" href="#배터리" aria-label="Permalink to &quot;배터리&quot;">​</a></h2><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>배터리가 장착된 상태로 항공·선박 운송 시 관련 규정(예: 유엔 위험물 규칙, 항공사 규정)을 확인하세요. 필요 시 배터리를 분리하고 별도로 운송할 수 있는지 매뉴얼 및 Rainbow Robotics에 문의하세요.</p></div></div><h2 id="도킹-스테이션·충전기" tabindex="-1">도킹 스테이션·충전기 <a class="header-anchor" href="#도킹-스테이션·충전기" aria-label="Permalink to &quot;도킹 스테이션·충전기&quot;">​</a></h2><ul><li><strong>충전기·도킹 스테이션</strong>: 별도 포장 및 운송 시 충격을 주지 않도록 하고, 케이블이 꼬이거나 눌리지 않게 하세요.</li></ul><h2 id="보관" tabindex="-1">보관 <a class="header-anchor" href="#보관" aria-label="Permalink to &quot;보관&quot;">​</a></h2><ul><li><strong>미사용 시</strong>: 사용하지 않을 때는 <strong>전용 케이스</strong>나 <strong>도킹 스테이션(도크)</strong>에 보관하세요. 케이스 규격·중량은 제품 동봉 안내를 참고하세요.</li><li><strong>보관 환경</strong>: <a href="/RBQ/ko/manual/safety/operating-environment-requirements.html">운영 환경 요구사항</a>에 따른 <strong>보관 온도·습도 범위</strong>를 지키세요. 배터리는 <a href="/RBQ/ko/manual/safety/battery-handling.html">배터리 취급 주의사항</a>의 보관 조건을 따르세요.</li></ul>',20)])])}const k=r(l,[["render",d]]);export{_ as __pageData,k as default};
